"""Authored lesson explanations and experiments; rendered by apply-editorial.py."""
LESSONS = {}


def add(id, goal, explain, command, expected, guided, independent, reflection, source,
        object='Страница заметок и выделенные ресурсы текущего опыта.'):
    LESSONS[id] = dict(goal=goal, explain=explain, command=command,
                      expected=expected, guided=guided, independent=independent,
                      reflection=reflection, source=source, object=object,
                      why='Сопоставь наблюдение с описанным механизмом. Вывод относится к проверенному объекту и условиям опыта.',
                      deviation='При несовпадении результата сохрани фактический вывод, проверь предпосылки и остановись перед дальнейшими изменениями. Не подменяй наблюдение ожидаемым текстом.',
                      rights='В учебном Linux-госте обычным пользователем; sudo требуется только для явно указанных изменений. Данные примера можно разбирать без стенда.')


add('address', 'Определить следующий узел для конкретного IP-адреса.',
    'IP-адрес обозначает сетевой интерфейс в адресном плане. Префикс описывает диапазон адресов. Таблица маршрутов выбирает путь: в выбранной таблице используется наиболее длинный подходящий префикс. Для непосредственного соседа Ethernet нужен его MAC; для адреса за маршрутизатором — MAC следующего узла. ARP находит IPv4-соседа только в своём сегменте. Маршрутизатор создаёт новый кадр для следующего участка. NAT может дополнительно менять IP-адреса, поэтому неизменность адреса назначения нельзя обещать для любого пути.',
    'sudo ip -n "$NS-a" route get 192.0.2.2\nsudo ip -n "$NS-a" neigh show',
    'В опыте address путь к 192.0.2.2 идёт через eth0 без via. После обмена таблица соседей может содержать MAC второго узла.',
    'До ping предскажи, чей MAC понадобится. Подготовь address, прочитай маршрут, выполни один ping внутри namespace a и повтори neigh. Сохрани маршрут в route.txt.',
    'Для клиентского адреса стенда и сервера в другой подсети нарисуй один кадр и один IP-пакет: MAC назначения шлюза и IP назначения сервера. Проверь фактический маршрут, не добавляя маршруты на основной ВМ.',
    'Почему MAC шлюза не означает, что IP-пакет адресован самому шлюзу? Повтори с другим удалённым префиксом.',
    'https://man7.org/linux/man-pages/man8/ip-route.8.html')
add('prefix', 'Исправить длину префикса на выделенном интерфейсе и проверить маршрут.',
    'Префикс /24 оставляет восемь бит для адресов внутри сети, /32 обозначает один IPv4-адрес. Подключённый маршрут зависит от адреса и длины префикса интерфейса. Слишком широкий префикс может заставить узел искать удалённый адрес через ARP вместо шлюза; слишком узкий — лишить маршрута до соседа. Для 10.8.3.190/26 сеть равна 10.8.3.128, broadcast — 10.8.3.191, обычные адреса узлов — .129–.190. Это правило нельзя механически переносить на /31, /32 или IPv6.',
    'sudo ip -n "$NS-a" -br address\nsudo ip -n "$NS-a" route get 192.0.2.2',
    'После подготовки prefix узел a имеет 192.0.2.1/32 и не имеет обычного подключённого маршрута к .2. После замены на /24 появляется прямой путь.',
    'Предскажи результат route get при /32. Удали только учебный адрес /32 и добавь тот же адрес /24 внутри namespace a. Повтори маршрут и ping. Не исправляй опыт обходным host route.',
    'После отката рассчитай сеть для 198.51.100.70/26. Затем повтори исправление новой попытки по её имени namespace.',
    'Почему работающий ping после ip addr add ещё не подтверждает сохранение настройки после перезагрузки? Назови службу, хранящую конфигурацию настоящего интерфейса.',
    'https://man7.org/linux/man-pages/man8/ip-address.8.html')
add('tcp', 'Проверить listener, соединение и содержимое HTTP как три отдельных результата.',
    'Порт различает транспортные конечные точки на одном адресе. TCP устанавливает соединение и передаёт упорядоченный поток байтов; границы вызовов send и recv не являются границами сообщений приложения. Приложение должно определять длину или разделитель. Listener означает готовность ядра принимать соединения на адресе и порту, но не гарантирует правильный ответ. HTTP-статус относится к ответу приложения; для файла дополнительно проверяют полное тело, длину и контрольную сумму.',
    'sudo ip netns exec "$NS-b" ss -lnt\nsudo ip netns exec "$NS-a" curl --fail --max-time 3 http://192.0.2.2:8080/',
    'В tcp виден 192.0.2.2:8080, а тело запроса равно note. Наличие только первой строки ещё не завершает проверку.',
    'Предскажи результат соединения с 8080 и с неиспользуемым 8089. Выполни обе пробы с ограничением ожидания. Сохрани правильное тело в response.txt.',
    'Повтори после новой подготовки, сохрани тело в файл и вычисли sha256sum. Объясни, почему успешное рукопожатие не заменяет сравнение содержимого.',
    'Какие четыре разных отказа могут находиться между listener и полной правильной заметкой? Через день восстанови последовательность проверок.',
    'https://man7.org/linux/man-pages/man7/tcp.7.html')
add('dns', 'Проверить DNS-запись отдельно от локального разрешения имени и HTTP.',
    'DNS связывает имя с записями, например A для IPv4 и AAAA для IPv6. dig обращается к выбранному DNS-серверу. getent использует настроенные в Linux источники NSS; результат может включать /etc/hosts и другие модули. Поэтому ответ dig не гарантирует тот же ответ у каждой программы: часть приложений имеет собственный резолвер. TTL ограничивает время кэширования записи, но не доказывает немедленное исчезновение всех старых ответов. Адрес из DNS ещё нужно проверить маршрутом, транспортом и приложением.',
    'sudo ip netns exec "$NS-a" dig @192.0.2.2 -p 5353 notes.test A +short\ngetent ahosts localhost',
    'Первый опыт даёт 192.0.2.2 от изолированного DNS-сервера. Второй относится к локальной настройке ВМ и другому имени; совпадать они не обязаны.',
    'Предскажи, меняет ли запрос dig системный DNS. Подготовь dns, запроси notes.test у явного сервера и сохрани адрес в address.txt. Системный resolv.conf не меняй.',
    'Запроси отсутствующее имя, сохрани полный ответ dig и различи NXDOMAIN, отсутствие A-записи и отсутствие ответа сервера. Не считай любой пустой +short доказанным NXDOMAIN.',
    'Как отличить неверное имя от недоступного HTTP-сервера по уже известному адресу? Повтори с другим типом записи.',
    'https://bind9.readthedocs.io/en/stable/manpages.html#dig-dns-lookup-utility')
add('mtu', 'Найти максимальный размер ICMP payload без фрагментации на учебном пути.',
    'MTU — максимальный размер IP-пакета на выбранном канальном участке; MTU пути ограничен наиболее узким участком. В IPv4 без опций ping -s задаёт данные ICMP, к которым добавляются 8 байт ICMP и 20 байт IP. Поэтому при MTU 1280 максимальный payload равен 1252. TCP-рукопожатие использует маленькие пакеты и не проверяет крупные ответы. Потеря ICMP, нужного для обнаружения MTU пути, может давать зависание передачи, но похожий симптом имеет и другие причины.',
    'sudo ip -n "$NS-a" link show eth0\nsudo ip netns exec "$NS-a" ping -c 1 -W 2 -M do -s 1252 192.0.2.2',
    'В варианте 0 1252 байта проходят, 1253 не проходят. В варианте 1 MTU равен 1380, поэтому предел payload — 1352.',
    'Предскажи размер полного пакета. Измерь проходящий и соседний непроходящий размер; сохрани максимальный payload в payload.txt. Не отключай запрет фрагментации ради успеха.',
    'Повтори вариант 1 без использования прежнего числа. Для реального туннеля запиши, в какой точке снят MTU и какие заголовки добавляет инкапсуляция.',
    'Почему MSS для IPv4/TCP без опций при MTU 1400 равен 1360, а не 1400? Повтори расчёт для другого MTU.',
    'https://man7.org/linux/man-pages/man8/ping.8.html')
add('ipv6', 'Настроить и проверить прямой IPv6-путь в изолированном сегменте.',
    'IPv6 использует 128-битные адреса. Префикс задаёт сеть, а соседей ищет Neighbor Discovery через ICMPv6, не ARP. У интерфейса может быть несколько адресов, включая link-local. Для link-local вне неоднозначного контекста нужен идентификатор интерфейса. В IPv6 нет IPv4 broadcast; бездумная блокировка ICMPv6 ломает необходимые механизмы. Наличие IPv4-связи не подтверждает IPv6, и наоборот.',
    'sudo ip -n "$NS-a" -6 address\nsudo ip -n "$NS-a" -6 route get 2001:db8::2',
    'После назначения 2001:db8::1/64 и ::2/64 двум узлам маршрут идёт через eth0. Префикс 2001:db8::/32 предназначен для документации и здесь используется в изоляции.',
    'Подготовь ipv6. Предскажи отсутствие нужного адреса до изменения; добавь адреса только в два namespace. В опыте допускается nodad для немедленной проверки, а на настоящей сети DAD не отключают без причины.',
    'Откати работу и повтори. Покажи IPv6-маршрут и успешный ping -6 независимо от IPv4. Объясни, почему не надо искать ARP-запись IPv6-соседа.',
    'Чем состояние tentative отличается от пригодного адреса? Позже проверь link-local и область действия без изменения основной сети.',
    'https://man7.org/linux/man-pages/man7/ipv6.7.html')
add('segments', 'Проверить принадлежность двух интерфейсов одному VLAN.',
    'VLAN разделяет домены второго уровня. Метка VLAN в кадре и IP-префикс решают разные задачи: одинаковый IP-префикс не соединяет раздельные VLAN. Мост пересылает кадры между разрешёнными портами; trunk должен пропускать нужные метки на всём пути. Для связи разных IP-подсетей используют маршрутизацию и подходящую политику. LACP объединяет линии, но обычный поток обычно попадает на одну линию по хешу. Один общий коммутатор остаётся общей точкой отказа.',
    'sudo ip -n "$NS-a" -d link show vlan10\nsudo ip -n "$NS-b" -d link show vlan10',
    'Оба интерфейса имеют VLAN ID 10. Только после назначения второго адреса появляется проверяемая связь в учебной подсети.',
    'Подготовь segments. Предскажи результат без адреса узла b, затем назначь 198.51.100.2/24 его vlan10. Подтверди метку и обмен между 198.51.100.1 и .2.',
    'Нарисуй случай: VM отправляет VLAN 30, uplink допускает только 10 и 20. Выбери точечное изменение списка разрешённых VLAN и проверку сохранения изоляции, не объединяя все порты.',
    'Что доказывает работа одной VLAN и чего она не доказывает о соседней? Повтори разбор с непомеченным портом.',
    'https://docs.kernel.org/networking/bridge.html')
add('firewall', 'Восстановить нужный обмен точечным правилом в изолированном фильтре.',
    'Маршрут выбирает путь, а межсетевой экран решает, разрешён ли пакет. Пакет самому маршрутизатору проходит input, пересылаемый пакет — forward; успех одного не подтверждает другого. NAT изменяет адреса или порты и не является самостоятельной моделью авторизации. Правило нужно читать вместе с цепочкой, порядком, состоянием соединения и политикой по умолчанию. Снятие всех правил прячет причину и меняет гораздо больше условий опыта.',
    'sudo ip netns exec "$NS-b" nft list ruleset\nsudo ip netns exec "$NS-a" ping -c 1 -W 2 192.0.2.2',
    'После подготовки firewall маршрут есть, но input узла b имеет policy drop. Точечное разрешение ICMP восстанавливает ping, сохраняя запрет остального входа.',
    'Предскажи, изменится ли route get после добавления правила. Подготовь firewall, сохрани исходные правила, разреши ICMP только в namespace b и повтори маршрут и ping.',
    'Разбери транзит через router: какой цепочки касается запрос к самому router и какой — к серверу за ним? Составь две разные проверки, не меняя реальный firewall ВМ.',
    'Почему работающий вход на маршрутизатор не подтверждает пересылку? Через день прочитай правило с ограничением протокола и адреса.',
    'https://wiki.nftables.org/wiki-nftables/index.php/Netfilter_hooks')

add('disk-identity', 'Установить идентичность учебного диска до любой записи.',
    'Имя /dev/sdX или /dev/vdX зависит от обнаружения и не является постоянной идентичностью носителя. Модель, серийный номер и WWN помогают связать устройство с карточкой. UUID файловой системы описывает содержимое, а PARTUUID — раздел; клонирование может создать дубликаты этих значений. Перед записью сопоставляют размер, назначение, связи с mount, LVM и RAID, а не выбирают первый свободный диск. Виртуальный диск может скрывать физический носитель и не иметь настоящего серийного номера.',
    'lsblk -J -o NAME,TYPE,SIZE,MODEL,SERIAL,WWN\nfindmnt -n -o SOURCE /',
    'Показано дерево устройств и корень системы. Отсутствующий SERIAL остаётся ограничением идентификации; это не признак пустого диска.',
    'Предскажи, какие устройства принадлежат корню. Подготовь disk-identity и сохрани JSON в observation.txt. Отметь, каких полей не хватает для безопасного выбора диска.',
    'Сопоставь два клонированных образа с одинаковым UUID и разными серийными номерами ВМ. Укажи, почему одной ссылки by-uuid недостаточно. Форматирование в этой работе не требуется.',
    'Какие три независимых признака проверишь перед mkfs? Повтори инвентаризацию после новой загрузки.',
    'https://man7.org/linux/man-pages/man8/lsblk.8.html')
add('disk-health', 'Отделить факты о носителе от ошибок контроллера и пути.',
    'Ошибка ввода-вывода может возникнуть в накопителе, кабеле, контроллере, драйвере или удалённом пути. SMART и NVMe health — источники сведений самого устройства, но отсутствие ошибок не доказывает исправность всей цепочки. Счётчик нужно читать с единицами, временем и смыслом производителя. Виртуальный диск обычно не передаёт физическую телеметрию. Ошибка transport вместе со сбросом контроллера требует проверки пути; одиночный атрибут без истории не устанавливает причину.',
    'lsblk -n -o NAME,TYPE,TRAN,MODEL\njournalctl -k -b --no-pager',
    'Первое наблюдение описывает видимые гостю устройства. Журнал может быть недоступен обычному пользователю; это ограничение прав, а не отсутствие ошибок.',
    'Подготовь disk-health и зафиксируй транспорт и модель. Сохрани observation.txt по инструкции. В разборе укажи, какие сведения должен предоставить администратор физического хоста.',
    'Разбери данные: media_errors не растёт, но увеличиваются reset и ошибки линка. Выбери следующую проверку пути и объясни, почему немедленная замена диска пока не доказана.',
    'Как сравнить счётчик до и после опыта, не потеряв время сброса устройства? Вернись к другому набору телеметрии.',
    'https://www.smartmontools.org/browser/trunk/smartmontools/smartctl.8.in')
add('filesystem', 'Различить исчерпание блоков и inode на отдельной файловой системе.',
    'Файловая система связывает имена, метаданные и блоки данных. inode описывает объект, каталог связывает имя с inode. Пустой файл может не иметь блоков содержимого, но расходует inode и запись каталога. df оценивает занятость файловой системы, du обходит доступные имена; расхождение бывает из-за открытого удалённого файла, резервов и других причин. unlink удаляет имя; блоки освобождаются после исчезновения ссылок и открытых дескрипторов. Поэтому повторное rm уже удалённого имени не закрывает чужой файл.',
    'df -B1 "$WORK/mnt"\ndf -i "$WORK/mnt"\ndu -B1 -s "$WORK/mnt/notes"',
    'В отдельной ext4 видны независимые счётчики байтов и inode. Создание множества пустых файлов увеличивает расход inode без такого же роста полезного содержимого.',
    'Предскажи изменение inode при создании 50 файлов. Подготовь filesystem и выполни опыт только в mnt/notes. Сохрани blocks.txt и inodes.txt, сравни до и после.',
    'Повтори второй вариант с 60 файлами. Затем разбери случай удалённого, но открытого журнала: найди удерживающий дескриптор в примере /proc/PID/fd и предложи поддерживаемое переоткрытие.',
    'Почему низкий du не доказывает наличие свободного места? Через день объясни жизненный цикл имени, inode и дескриптора.',
    'https://man7.org/linux/man-pages/man2/unlink.2.html')
add('lvm', 'Расширить логический том и ext4 как два отдельных слоя, сохранив заметку.',
    'LVM объединяет physical volume в volume group и выделяет logical volume. Файловая система использует размер логического блочного устройства, но не обязана автоматически расти при увеличении LV. Для ext4 размер увеличивают resize2fs; команды других ФС отличаются. Расширение и уменьшение — разные операции с разными ограничениями. mkfs создаёт новую файловую систему и не служит командой расширения. Проверка после изменения включает размер LV, размер ФС и сохранность содержимого.',
    'sudo lvs --units m\nfindmnt "$WORK/mnt"\ndf -h "$WORK/mnt"',
    'В подготовленной работе LV notes имеет 16 MiB, ext4 смонтирована, note.txt содержит keep me. Цель варианта 0 — LV 32 MiB и выросшая ext4; варианта 1 — 48 MiB.',
    'Предскажи, изменится ли df после одного lvextend. На выделенном /dev/NS/notes увеличь LV до требуемого размера, затем выполни resize2fs. Сравни два слоя и прочитай заметку.',
    'Откати и повтори вариант 1. Перед каждой изменяющей командой докажи, что VG совпадает с NS своей попытки. Системные VG не трогай.',
    'Почему увеличение виртуального диска Proxmox само по себе не увеличивает ext4 внутри LV? Вернись к цепочке диск → PV → VG → LV → ФС.',
    'https://man7.org/linux/man-pages/man8/lvextend.8.html')
add('mirror', 'Определить состояние RAID1 после отказа одного учебного участника.',
    'RAID1 хранит копии блоков на участниках зеркала. После отказа одного участника массив может продолжать работать в degraded, но избыточность уже потеряна. Удаление файла и повреждение содержимого также могут попасть во все копии, поэтому RAID не заменяет резервную копию. Скорость rebuild ограничена накопителями, нагрузкой и политикой; расчёт размера/скорости даёт лишь нижнюю оценку. В опыте используются только два файловых образа и их loop-устройства.',
    'cat /proc/mdstat\nsudo mdadm --detail "/dev/md/$NS"',
    'До отказа видны два активных участника, после намеренного отказа одного — один рабочий участник и degraded. Заметка остаётся читаемой.',
    'До отказа предскажи состояние и доступность данных. Сверь оба участника с файлами своей попытки; выведи один из массива штатной командой mdadm, затем проверь состояние и заметку.',
    'После отката повтори на втором варианте и укажи оставшийся исправный участник. Не выполняй fail/remove над устройствами вне списка подготовки.',
    'Почему читаемый файл ещё не означает, что отказоустойчивость восстановлена? Через день объясни различие degraded и healthy.',
    'https://docs.kernel.org/admin-guide/md.html')
add('storage-path', 'Нарисовать все узлы между приложением и носителем, выделив общие точки отказа.',
    'Запрос записи проходит приложение, файловую систему, блочный слой, драйвер, контроллер, канал и накопитель. Разные имена устройств могут вести к одному носителю, а два контроллера — к общему питанию. SATA, SAS и NVMe описывают разные интерфейсы и пути; разъём и скорость линка не определяют полезную производительность нагрузки. Карта должна показывать идентичность тома и независимость пути отдельно. Резервирование числа кабелей недостаточно, если их общий узел остаётся единственным.',
    'приложение → ext4 → LV → multipath → HBA A/B → общий массив → носители\nHBA A и B питаются от одного узла',
    'Два HBA не исключают отказ общего массива или общего питания. Карта позволяет назвать проверяемый отказ вместо заявления «всё зарезервировано».',
    'Предскажи, какие узлы затронет отказ одного HBA. Отметь на схеме два пути и все общие компоненты. Свяжи ошибки приложения с источниками наблюдений на каждом слое.',
    'Добавь независимый коммутатор хранения, но оставь один контроллер массива. Объясни, какой отказ устранён, а какой остался.',
    'Как доказать независимость путей испытанием? Повтори рисунок для локального NVMe.',
    'https://docs.kernel.org/admin-guide/device-mapper/index.html')
add('write-cache', 'Назвать границу долговечности после подтверждения записи.',
    'Успешный write обычно означает приём байтов ядром, а не сохранение на энергонезависимом носителе. fsync запрашивает устойчивое сохранение файла в рамках контракта файловой системы и нижних слоёв; создание имени может требовать синхронизации каталога. Контроллер и накопитель должны корректно выполнять flush/FUA, а защищённый кэш — соответствовать заявленному отказу. Журнал ФС не делает любой прикладной протокол транзакционным. Нужно спрашивать: кто подтвердил запись, какие данные охвачены и при каком отказе обещано восстановление.',
    'программа: write вернул 4096\nядро: данные в page cache\nпитание всего пути потеряно до устойчивой записи',
    'Одного write недостаточно для обещания сохранности этих 4096 байт после отключения питания. Это не утверждение, что данные обязательно потеряны.',
    'Предскажи, какие обещания меняются после fsync. Раздели подтверждение принятия, завершение синхронизации и проверенное восстановление. Назови сведения, нужные о кэшах контроллера и накопителя.',
    'Разбери создание нового файла через временное имя и rename. Укажи, почему долговечность содержимого и долговечность записи каталога — разные вопросы.',
    'Какой тест отличает контракт от фактической устойчивости? Отключение питания реального оборудования в этот урок не входит.',
    'https://man7.org/linux/man-pages/man2/fsync.2.html')
add('network-storage', 'Различить удалённую файловую систему и удалённое блочное устройство.',
    'NFS предоставляет операции над файлами через сервер, iSCSI — блочное устройство, поверх которого клиент может создавать ФС. Обычная локальная ext4 не становится кластерной при подключении одного LUN к двум писателям: несогласованные метаданные могут разрушить данные. Для совместного доступа нужен подходящий протокол, блокировки и модель владения. Зависание удалённого хранения проявляется в процессах клиента и требует проверки сервера и сети, а не только локального CPU.',
    'findmnt -o TARGET,SOURCE,FSTYPE\nlsblk -o NAME,TYPE,FSTYPE,MOUNTPOINTS',
    'В подготовленном файловом опыте SOURCE содержит сервер и экспорт, FSTYPE — nfs/nfs4. В блочном опыте появляется устройство; способ доступа отличается до уровня ФС.',
    'Предскажи, в каком выводе будет виден NFS mount. Подключи только выделенный экспорт, запиши заметку и прочитай её на серверной стороне. Подтверди тип источника.',
    'Для одного iSCSI LUN и двух клиентов предложи безопасную схему единственного писателя. Объясни, почему второй mount -o rw обычной ext4 недопустим.',
    'Какой слой подтверждает блокировку имени файла и какой — доступность пути к LUN? Повтори на другой схеме.',
    'https://docs.kernel.org/admin-guide/nfs/index.html')
add('multipath', 'Подтвердить, что два пути ведут к одному LUN и переживают отказ одного пути.',
    'DM Multipath объединяет пути к одному блочному устройству по устойчивой идентичности, обычно WWID. Два разных диска одинакового размера не становятся путями к одному LUN. Активное отображение не доказывает независимость коммутаторов и питания. Политика queue_if_no_path может превращать полный отказ путей в длительное ожидание, поэтому время отказа — часть контракта. Приёмка включает WWID, состояние путей и непрерывность чтения при отказе одного выделенного канала.',
    'sudo multipath -ll\nlsblk -o NAME,TYPE,SIZE,WWN',
    'Один multipath map объединяет два пути одного WWID; при потере одного остаётся пригодный путь к тому же содержимому.',
    'До отключения нарисуй оба канала и назови оставшийся путь. Сверь WWID и только затем выведи из работы один учебный канал по карточке. Продолжай чтение известного файла.',
    'Верни первый канал, дождись штатного состояния и повтори отказ второго. Два последовательных успеха не подтверждают отказ общего массива — укажи эту границу.',
    'Почему два /dev/sdX сами по себе ничего не доказывают о двух LUN? Через день объясни поведение при потере всех путей.',
    'https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9/html/configuring_device_mapper_multipath/index')
add('zfs', 'Восстановить содержимое снимка в отдельном пуле и проверить файл.',
    'Пул ZFS объединяет устройства, dataset задаёт отдельное пространство данных, snapshot фиксирует состояние dataset. Снимок в том же пуле зависит от его сохранности. zfs send формирует поток снимка, zfs receive принимает его в другой dataset. Наличие снимка и наличие независимой восстановленной копии — разные результаты. Проверка восстановления читает файл в целевом пуле и сравнивает содержимое или хеш, не довольствуясь списком snapshots.',
    'sudo zpool status\nsudo zfs list -t filesystem,snapshot',
    'После подготовки есть два отдельных пула на выделенных файловых образах. Исходный dataset содержит note.txt и снимок; восстановление должно появиться в другом пуле.',
    'Предскажи, переживёт ли снимок уничтожение собственного пула. Отправь снимок потоком в целевой пул без флага принудительного уничтожения. Прочитай восстановленный файл и сравни SHA-256.',
    'Откати и повтори с другим содержимым. Проверь, что отчёт относится к новой попытке, а не к файлу предыдущего запуска.',
    'Почему два dataset в одном пуле не дают независимую копию? Через день восстанови цепочку snapshot → send → receive → чтение.',
    'https://openzfs.github.io/openzfs-docs/man/master/8/zfs-send.8.html')
add('ceph', 'Определить состояние объектов Ceph по репликам и правилам размещения.',
    'Ceph распределяет объекты по OSD через placement groups и правила CRUSH. Число копий само по себе не задаёт независимость: копии должны попадать в разные допустимые домены отказа. size задаёт желаемое число реплик, min_size ограничивает возможность ввода-вывода при их нехватке. Снижение min_size ради исчезновения ошибки меняет риск потери данных. HEALTH_OK не заменяет проверку размещения и чтение нужного объекта.',
    'pool: size=3, min_size=2\nобъект A: копии на host1, host2, host3\nhost3 недоступен',
    'Осталось две копии, желаемая избыточность не достигнута. Допустимость операции зависит от реального состояния PG и политики, а не только от арифметики.',
    'Предскажи отличие между потерей одного OSD и целого host. По данным нарисуй размещение и выбери наблюдение PG, которое подтвердит доступность объекта.',
    'Перенеси две копии на один host в схеме. Найди новый общий отказ, не меняя size. Объясни, какие данные нужны перед восстановлением реплик.',
    'Почему кратковременное возвращение HEALTH_OK ещё не показывает скорость восстановления после следующего отказа? Повтори с другой картой CRUSH.',
    'https://docs.ceph.com/en/latest/rados/operations/pools/')
add('benchmark', 'Сравнить накопители при одинаковом профиле и точке измерения.',
    'IOPS — число операций в секунду; без размера операции и шаблона доступа оно мало говорит о полезной работе. Сравнение требует одинаковых read/write, random/sequential, block size, queue depth, числа исполнителей, кэша, длительности и рабочего набора. Пропускная способность приближённо равна IOPS × размер блока для определённого профиля. Высокая очередь может увеличить throughput и одновременно ухудшить задержку. Один лучший запуск не описывает разброс и прогрев.',
    'A: 40000 IOPS, 4 KiB random read, QD32\nB: 12000 IOPS, 64 KiB sequential write, QD1',
    'Из этих чисел нельзя выбрать универсально более быстрый диск. Различаются операция, размер, доступ и очередь.',
    'Предскажи, какой вывод пока недопустим. Составь единый манифест нагрузки, точку измерения и план повторов; укажи latency и ошибки вместе с throughput.',
    'Даны 10000 операций/с по 4 KiB. Найди 40 960 000 B/s и переведи отдельно в MB/s и MiB/s. Затем объясни, почему этот расчёт не измеряет долговечность записи.',
    'Какая часть испытания прогревает кэш и какая измеряет? Вернись к двум сериям с одинаковым средним и разным разбросом.',
    'https://fio.readthedocs.io/en/latest/fio_doc.html')
add('latency', 'Показать медленный хвост по исходным измерениям, а не только по среднему.',
    'Задержка относится к определённой операции и точке измерения. Среднее описывает сумму, делённую на число наблюдений; редкие медленные ответы могут быть почти незаметны в нём. Монотонные часы подходят для длительности внутри одной системы, поскольку не предназначены для календарной коррекции. Процентиль требует согласованного определения; для малого ряда лучше показать сами значения и максимум. Ожидание sleep в опыте измеряется реально, но не является моделью всей серверной нагрузки.',
    'python3 -c "import time; s=time.monotonic(); time.sleep(0.2); print((time.monotonic()-s)*1000)"',
    'Около 200 ms или больше: планировщик может возобновить процесс позже. Результат меньше планового ожидания требует проверки кода и единиц.',
    'Предскажи среднее ряда из четырёх ожиданий 10 ms и одного 200 ms. Создай measure.py, принимающую длительности из аргументов и печатающую JSON samples_ms, mean_ms, max_ms. Исполнитель реально запустит программу с разными ожиданиями от имени ученика. Сравни среднее и максимум.',
    'Добавь второй медленный ответ и повтори расчёт на новом ряду. Укажи количество наблюдений и не выводи p99 крупной системы из пяти опытов.',
    'Почему среднее двух p99 не даёт общий p99? Через день объединяй исходные ряды, а не готовые процентили.',
    'https://docs.python.org/3/library/time.html#time.monotonic')
add('database-write', 'Установить, что означает подтверждение транзакции при заданной политике записи.',
    'База данных может сначала записать журнал изменений, затем страницы данных. Write-ahead logging обеспечивает порядок восстановления, но конкретные гарантии зависят от синхронизации журнала, репликации и нижнего хранения. Асинхронная реплика может отставать после успешного ответа клиенту. Количество копий не заменяет условие их подтверждения. Перед обещанием нулевой потери называют отказ, границу COMMIT и доказанные свойства каждого слоя.',
    'клиент получил COMMIT\nprimary: журнал синхронизирован\nреплика: отстаёт на 3 секунды\nprimary потерян безвозвратно',
    'Успешный COMMIT на primary не доказывает наличие последней транзакции на асинхронной реплике. Фактическая потеря зависит от того, какие записи успели дойти.',
    'Предскажи, какое утверждение о реплике пока нельзя сделать. Нарисуй точки подтверждения и запроси LSN/позицию реплики и политику synchronous_commit для конкретной версии БД.',
    'Измени условие: COMMIT ждёт устойчивой записи на выбранной реплике. Объясни, какая гарантия усилилась, какие задержки добавились и какие общие отказы остались.',
    'Почему fsync одного слоя не доказывает восстановление приложения? Повтори разбор другой политики репликации.',
    'https://www.postgresql.org/docs/current/wal-reliability.html')
add('restore-point', 'Отделить наличие копии от доказанного восстановления до нужного момента.',
    'Резервная копия полезна, если известны её состав, время, версия, ключи и процедура восстановления. RPO задаёт допустимую потерю данных во времени, RTO — допустимое время возврата работы. Снимок, реплика и архив журнала решают разные задачи. Для восстановления на момент времени нужны согласованная базовая копия и непрерывная цепочка необходимых журналов. Проверка должна включать чтение данных и прикладной запрос в изолированной восстановленной системе.',
    'копия: 10:00\nжурналы: непрерывно до 10:42\nошибка оператора: 10:35\nцель: состояние 10:34',
    'Цель может быть достижима при подходящем формате копии и журналов. Сам список файлов этого не доказывает; требуется пробное восстановление.',
    'Предскажи, почему восстановление последней реплики может вернуть уже ошибочное удаление. Выбери точку до ошибки и перечисли артефакты для изолированного запуска.',
    'Добавь разрыв журналов в 10:20. Пересмотри достижимую точку, не обещая произвольные 10:34. Составь проверку количества и содержания заметок после возврата.',
    'Как измерить время до действительно работающего сервиса, а не до завершения копирования файлов? Повтори с другой точкой отказа.',
    'https://www.postgresql.org/docs/current/continuous-archiving.html')

add('shell-data', 'Передать точные имена файлов, содержащие пробелы.',
    'Bash разбивает непроцитированное значение переменной на слова и может раскрывать шаблоны. Имя first note должно остаться одним аргументом, а не двумя. Нулевой байт не встречается в имени Linux-файла, поэтому find -print0 и команды с поддержкой NUL подходят для надёжной передачи списка имён. Перевод строки внутри имени допустим; обычный построчный список не универсален. Кавычки вокруг "$path" сохраняют границу одного аргумента, а -- отделяет параметры от имени, начинающегося с дефиса.',
    'find "$WORK/input" -type f -printf "%f\\0" | sort -z > "$WORK/names.bin"',
    'names.bin содержит каждое имя целиком, в сортированном порядке и с NUL-разделителями; пробелы не исчезают.',
    'Предскажи результат для first note и second note. Подготовь shell-data, сравни обычное перечисление с NUL-списком. Сохрани именно имена, без пути input.',
    'Во втором варианте список длиннее. Получи его без ручного перечисления имён и объясни, почему цикл for f in $(ls) не годится.',
    'Какие два разных механизма предотвращают кавычки и NUL? Завтра добавь имя с переводом строки в отдельный тестовый каталог.',
    'https://www.gnu.org/software/findutils/manual/html_mono/find.html')
add('shell-failure', 'Остановить слишком долгую команду и обработать её код завершения.',
    'Код завершения — числовой результат процесса; 0 обычно обозначает успех по контракту программы. stdout и stderr передают данные независимо от кода. В Bash set -e имеет исключения и не заменяет явную обработку ожидаемых отказов. Pipefail меняет код конвейера, но не откатывает выполненные действия. GNU timeout ограничивает длительность и обычно возвращает 124 при срабатывании; специальные режимы и сигналы имеют другие коды. Повторы допустимы только при понятной идемпотентности и ограниченном числе попыток.',
    'timeout 1 sleep 30\nprintf "код: %s\\n" "$?"',
    'В интерактивной оболочке без set -e после примерно секунды виден код 124. Неуспех здесь ожидается и является предметом опыта.',
    'Предскажи отличие ненулевого кода от отсутствующего stdout. Подготовь shell-failure, сначала проверь $? вручную, затем сохрани обработку в solution.sh: предел ожидания приходит первым аргументом. Следующая команда меняет $?, поэтому код запоминают сразу.',
    'Во втором варианте предел равен двум секундам. Напиши явное ветвление по коду и объясни, почему бесконечный повтор может усилить отказ сервиса.',
    'Что известно после timeout и чего он не доказывает о причине ожидания? Повтори с командой, сразу возвращающей код 7.',
    'https://www.gnu.org/software/coreutils/manual/html_node/timeout-invocation.html')
add('python-result', 'Получить структурированный результат внешней команды без смешивания каналов.',
    'Python может запускать программу через subprocess.run. Список аргументов с shell=False передаёт границы прямо процессу; shell=True добавляет интерпретацию оболочкой и требует другой модели безопасности. capture_output разделяет stdout и stderr, text декодирует байты, timeout ограничивает ожидание. Ненулевой returncode нужно обработать либо явно, либо через check=True и исключение. JSON сериализует поля результата, но не превращает неуспех в успех. Отсутствующее поле, null и ноль имеют разные значения.',
    'python3 -c "import subprocess; r=subprocess.run([\'python3\',\'-c\',\'import sys; print(7); sys.exit(3)\'],capture_output=True,text=True,timeout=3); print(repr(r.stdout),repr(r.stderr),r.returncode)"',
    'stdout содержит 7 и перевод строки, stderr пуст, returncode равен 3. Наличие полезного stdout не обнуляет отказ.',
    'Предскажи три поля результата программы из задания. Подготовь python-result; запусти дочерний Python, печатающий out в stdout, err в stderr и завершающийся с 7. Сохрани решение в solution.py, принимающей команду как список sys.argv[1:] и печатающей JSON stdout, stderr, code. Исполнитель запустит её от имени ученика с разными командами.',
    'Измени дочернюю программу так, чтобы stdout был пустым, и обработай TimeoutExpired отдельно от ненулевого кода. Не используй shell=True для склейки пользовательских аргументов.',
    'Почему код 0 не доказывает полноту предметного результата? Через день восстанови обработку трёх исходов: успех, отказ, тайм-аут.',
    'https://docs.python.org/3/library/subprocess.html')
add('api-pages', 'Собрать все страницы данных API, обнаруживая неполный результат.',
    'API — программный интерфейс с форматом запроса и ответа. Список объектов может приходить страницами; одна успешная HTTP-страница не доказывает полноту набора. Следующий cursor обычно непрозрачен: его используют по контракту, а не угадывают арифметикой. В процессе обхода данные могут меняться, поэтому проверяют snapshot/version или условия согласованности. Повтор запроса после ошибки должен учитывать идемпотентность, rate limit и Retry-After. Отчёт хранит признаки полноты, а не только число полученных строк.',
    'страница 1: ids=[1,2], next=abc\nстраница 2: ids=[3], next=null\nожидаемая версия набора: v17',
    'Полный набор этого примера равен [1,2,3], если обе страницы относятся к v17. Остановка после первой страницы даёт неполный успех.',
    'Предскажи условие завершения. Нарисуй цикл: запрос → проверка кода и схемы → сохранение объектов → переход по next. Добавь защиту от повторяющегося cursor.',
    'Вторая страница вернула 503. Составь результат, который не выдаёт [1,2] за полный набор. Укажи, когда допустим ограниченный повтор.',
    'Какая гарантия нужна для обхода меняющегося списка без пропусков? Повтори с дублирующимся id.',
    'https://www.rfc-editor.org/rfc/rfc9110.html')
add('git-change', 'Сохранить изменение конфигурации отдельным объяснимым коммитом.',
    'Git хранит снимки отслеживаемых файлов и связи между коммитами. Рабочее дерево, индекс и последний коммит — три разных состояния. diff показывает выбранную разницу, а status — незафиксированные изменения. Коммит конфигурации не разворачивает её в сервисе и не проверяет применимость. Секреты нельзя считать удалёнными из истории после простого удаления файла новым коммитом. Безопасный учебный репозиторий содержит только созданную работой конфигурацию и фиктивные данные.',
    'git -C "$WORK/repo" status --short\ngit -C "$WORK/repo" diff\ngit -C "$WORK/repo" log -1 --oneline',
    'В начале есть baseline и port=8080. После задачи нужен второй коммит с port=8081 или 8082 и чистое рабочее дерево.',
    'Предскажи, попадёт ли незастейдженный файл в коммит. Подготовь git-change, измени порт, прочитай diff, добавь только service.conf в индекс и закоммить с причиной изменения.',
    'Повтори второй вариант. Покажи различие baseline и нового коммита и объясни способ возврата отдельного изменения без переписывания чужой истории.',
    'Какое испытание нужно сверх чистого git status для проверки работающего сервиса? Через день восстанови три состояния файла.',
    'https://git-scm.com/docs/git-diff')
add('ansible-state', 'Подтвердить сходимость конфигурации повторным запуском Ansible.',
    'Ansible применяет задачи к выбранным inventory-узлам. Декларативный модуль описывает требуемое состояние; произвольная shell-команда не становится идемпотентной автоматически. changed показывает заявленное изменение, failed — отказ. Второй запуск без изменений проверяет сходимость конкретного playbook, но не отсутствие всех побочных эффектов. Check mode зависит от поддержки модулей и не заменяет реальный прогон. Inventory и become нужно проверять до изменения, чтобы не затронуть другой сервер.',
    'ansible-playbook -i localhost, "$WORK/site.yml"',
    'Первый запуск создаёт service.conf с нужным портом и режимом 0600. Второй должен дать changed=0 и failed=0.',
    'Предскажи состояние после двух запусков. Подготовь ansible-state, прочитай hosts и connection в site.yml, выполни два запуска и сохрани first.log и second.log.',
    'Измени значение порта в своей конфигурации и повтори: один запуск меняет состояние, следующий сходится. Не используй inventory настоящих серверов.',
    'Почему changed=0 не доказывает правильный HTTP-ответ? Через день сопоставь конфигурационную и прикладную проверки.',
    'https://docs.ansible.com/ansible/latest/playbook_guide/playbooks_checkmode.html')
add('vm-resources', 'Сопоставить ресурсы гостя с конфигурацией гипервизора и границами наблюдения.',
    'Виртуальная машина получает виртуальные CPU, память и устройства от гипервизора. Гость видит представление ресурсов, а не всю топологию физического хоста. Большое число vCPU не обещает столько же одновременно свободных физических ядер; overcommit и конкуренция влияют на задержки. NUMA-топология гостя должна соответствовать задаче и политике хоста. Наблюдения внутри ВМ сравнивают с карточкой гипервизора, не объявляя их независимой проверкой физического оборудования.',
    'lscpu -J\ngrep "^MemTotal:" /proc/meminfo',
    'Получены топология CPU и память, доступная гостю. MemTotal может быть меньше назначенного объёма из-за резервов и особенностей ядра.',
    'Предскажи число CPU по карточке ВМ. Подготовь vm-resources и сохрани оба вывода в observation.txt. Сравни с конфигурацией Proxmox, отметь отличия.',
    'По двум карточкам с одинаковым числом vCPU, но разной конкуренцией на хосте предложи измерение задержки. Не делай вывод о физической скорости по одному lscpu.',
    'Что гость не может доказать о размещении на хосте? Вернись к этой границе в опыте NUMA.',
    'https://pve.proxmox.com/pve-docs/pve-admin-guide.html#chapter_qm')
add('vm-backup', 'Восстановить отдельную копию ВМ и проверить данные и запуск приложения.',
    'Снимок зависит от исходного хранилища; резервная копия должна иметь подходящую независимость от проверяемого отказа. Успешный vzdump подтверждает завершение задания, а не работоспособность восстановленной программы. Для проверки используют новый VMID и изолированную сеть, чтобы копия не конфликтовала с оригиналом. Согласованность дисков и приложений зависит от режима копирования и координации с гостем. Ключи, внешние тома и сетевые зависимости могут не входить в архив автоматически.',
    'исходная ВМ: заметка rev=17\nрезервная копия → новый VMID → изолированный запуск → чтение rev=17',
    'Приёмка включает загрузку восстановленной ВМ и чтение ожидаемой заметки. Наличие архива без запуска не завершает опыт.',
    'До копирования запиши VMID, версию заметки, хеш данных и зависимости. Создай копию штатным средством Proxmox; восстанови в отдельный выделенный VMID без внешней сети. Проверь приложение через консоль гостя.',
    'Повтори после изменения заметки. Докажи, что восстановлена новая версия, а не прежний снимок. Измерь время до ответа приложения, не только до окончания qmrestore.',
    'Какие ресурсы остались за границами архива? Через день восстанови копию по одному протоколу без памяти о первом запуске.',
    'https://pve.proxmox.com/pve-docs/pve-admin-guide.html#chapter_vzdump')
add('container', 'Установить границы процесса контейнера и постоянных данных.',
    'Контейнер изолирует процессы и ресурсы средствами ядра хоста, а не запускает собственное ядро как обычная ВМ. Образ задаёт исходный файловый слой, запущенный контейнер добавляет изменяемый слой. Удаление контейнера может удалить этот слой; volume или bind mount имеют другой жизненный цикл. Лимиты задаются cgroups, изоляция зависит от namespaces, прав и конфигурации. Сам факт запуска в Docker не даёт универсальной границы безопасности.',
    'sudo docker inspect "$NS"\nsudo docker exec "$NS" uname -r',
    'В учебном опыте видны mount с заметкой и PID контейнера. Версия ядра относится к ядру Docker-хоста, включая случай Docker внутри ВМ.',
    'Предскажи судьбу заметки внутри слоя и в выделенном bind mount. Подготовь container, найди Mounts и процесс, сохрани наблюдение. Пересоздай только свой контейнер с тем же хранилищем.',
    'Повтори на втором варианте, докажи сохранность заметки после пересоздания и укажи, какой объект обеспечил сохранение. Не удаляй все контейнеры или volumes.',
    'Почему контейнер не равен отдельному ядру? Через день нарисуй образ, процесс и данные отдельно.',
    'https://docs.docker.com/engine/storage/')
add('container-network', 'Опубликовать HTTP-порт и проверить адрес прослушивания внутри контейнера.',
    'Адрес 127.0.0.1 внутри контейнера относится к его сетевому пространству, а не к Docker-хосту. Публикация порта перенаправляет трафик, но программа должна принимать его на подходящем интерфейсе. -p 127.0.0.1:18080:8080 ограничивает опубликованный адрес хоста; в Docker до 28.0.0 была оговорка о доступе из того же L2-сегмента, поэтому локальность нельзя обещать для произвольной версии. EXPOSE документирует порт образа и не равен публикации.',
    'sudo docker port "$NS"\ncurl --fail --max-time 3 http://127.0.0.1:18080/',
    'После исправления приложение слушает 0.0.0.0:8080 внутри контейнера, а наружу опубликован только локальный учебный порт.',
    'Предскажи, исправит ли публикация приложение, слушающее только внутренний loopback. Подготовь container-network, прочитай параметры запуска, исправь только свою конфигурацию и проверь тело.',
    'Повтори с портом 18081. Отдельно покажи внутренний listener и опубликованный адрес; не принимай docker ps за прикладную проверку.',
    'В чьём пространстве находится каждый 127.0.0.1 на схеме? Позже проверь ту же разницу для Pod.',
    'https://docs.docker.com/engine/network/port-publishing/')
add('delivery', 'Связать исходный коммит, проверенный артефакт и установленную версию.',
    'CI запускает проверки изменения, CD доставляет артефакт в среду. Между ними нужна идентичность: какой коммит собран, какие зависимости использованы и какой хеш установлен. Повторная сборка после проверки может дать другой артефакт. Зелёный pipeline не доказывает работоспособность опубликованной версии. После выпуска проверяют фактическую версию и пользовательский сценарий; откат должен ссылаться на известный пригодный артефакт, а не на неопределённый latest.',
    'commit A → build sha256:X → tests X → deploy X → запрос version=A\nrollback: ранее проверенный sha256:Y',
    'Цепочка проверяема только при совпадении артефакта. Пересборка в deploy без сравнения нарушает это доказательство.',
    'Предскажи, что сломается при использовании плавающего тега. Составь протокол выпуска заметок: коммит, хеш артефакта, проверки, среда, запрос после установки.',
    'Pipeline зелёный, но сервер сообщает предыдущий коммит. Выбери следующий факт для проверки доставки, не объявляя тесты ложными.',
    'Как отличить ошибку сборки от ошибки установки? Через день восстанови происхождение артефакта по протоколу.',
    'https://docs.github.com/en/actions/concepts/workflows-and-actions/workflow-artifacts')
add('terraform', 'Прочитать план инфраструктуры и обнаружить замену ресурса до применения.',
    'Terraform сопоставляет конфигурацию, состояние и наблюдаемую инфраструктуру. Plan показывает предполагаемые действия на момент построения; apply выполняет их с текущими условиями. Изменение может требовать replacement вместо правки на месте, а уничтожение ресурса — потери данных. State хранит привязки и может содержать секреты. Ручной дрейф не исправляется безопасно одним фактом запуска Terraform: сначала понимают его происхождение и желаемое состояние.',
    'план: + новая ВМ\nплан: -/+ замена диска notes\nданные диска: единственный экземпляр',
    'Применение плана с replacement единственного диска требует остановки и пересмотра: декларация не заменяет копию и план миграции.',
    'Предскажи, какие действия обратимы. Отметь создание, изменение и замену; для диска выпиши данные, резервную копию и критерий сохранения.',
    'Измени сценарий: диск внешний и управляется отдельно. Пересмотри границы Terraform и проверь, какой ресурс действительно будет удалён.',
    'Почему сохранённый plan связан с конкретными условиями? Через день прочитай другой план без apply.',
    'https://developer.hashicorp.com/terraform/cli/commands/plan')
add('kubernetes', 'Различить Running Pod и готовность приложения принимать запрос.',
    'Pod объединяет контейнеры с общей сетью и связанным жизненным циклом. Фаза Running означает, что Pod назначен узлу и контейнеры созданы; она не равна Ready. Readiness probe управляет готовностью принимать трафик, liveness probe может инициировать перезапуск, startup probe откладывает другие пробы во время старта. Неверная liveness может создать цикл перезапусков исправного, но медленного приложения. Проверка включает условия Pod, события и реальный запрос.',
    'kubectl -n "$NS" get pods\nkubectl -n "$NS" describe pod notes',
    'В подготовленном опыте Pod может быть Running и 0/1 Ready из-за неверного пути readiness. Исправление не должно удалять пробу.',
    'Предскажи состояние для работающего HTTP-сервера и readiness на отсутствующем пути. Подготовь kubernetes, прочитай события и исправь путь на доступный. Дождись Ready.',
    'Повтори вариант с другой ошибкой порта. Подтверди готовность и содержимое приложения, не ограничиваясь успешным apply.',
    'Когда рестарт полезен, а когда readiness должна лишь убрать трафик? Через день выбери пробу для медленной инициализации.',
    'https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/')
add('service-selector', 'Проследить Service до выбранного Pod и восстановить правильный selector.',
    'Service даёт стабильную точку обращения к набору конечных точек. Selector выбирает Pod по labels; targetPort задаёт порт назначения. Совпадение имени Service с именем Pod ничего не связывает автоматически. EndpointSlice показывает фактические конечные точки и их состояние. Ошибка может находиться в selector, readiness, порте или самом приложении. Поэтому существование ClusterIP не доказывает маршрут запроса до готового процесса.',
    'kubectl -n "$NS" get svc notes -o yaml\nkubectl -n "$NS" get pods --show-labels\nkubectl -n "$NS" get endpointslices',
    'После исправления selector выбирает готовый Pod notes; EndpointSlice содержит его адрес. Запрос из тестового Pod возвращает ожидаемую страницу.',
    'Предскажи endpoint для несовпадающих app=notes и app=wrong. Подготовь service-selector, сравни метки, исправь selector в своём namespace и проверь конечные точки и HTTP.',
    'Повтори с правильным selector, но неверным targetPort. Покажи, какое наблюдение отличает этот отказ от пустого набора endpoints.',
    'Почему правка DNS не исправляет неверный targetPort? Через день нарисуй путь DNS → Service → EndpointSlice → Pod → listener.',
    'https://kubernetes.io/docs/concepts/services-networking/service/')

add('cpu-numa', 'Связать размещение процесса с доступом к памяти на NUMA-системе.',
    'Сокет, ядро и аппаратный поток — разные уровни CPU. NUMA разделяет память на узлы с разной стоимостью доступа от конкретного процессора. Привязка CPU без учёта размещения страниц может увеличить удалённый доступ. Политика first touch связывает первичное размещение с обращением, но итог зависит от ядра и настроек. ВМ может показывать один NUMA-узел или виртуальную топологию; это не испытание физической платы. Закон Амдала ограничивает ускорение последовательной частью: при доле 0,15 и 12 исполнителях идеальное ускорение около 4,528.',
    'lscpu\nnumactl --hardware\nnumastat',
    'Видны CPU и доступные NUMA-узлы. Если узел один, опыт сравнения локальной и удалённой памяти не выполнен — нужен подходящий гость или физическая система.',
    'Предскажи, можно ли сравнить локальный и удалённый доступ в своей среде. Сверь CPU и память каждого узла. На подходящей системе измерь одну и ту же ограниченную нагрузку с согласованным и удалённым размещением.',
    'Повтори с тем же рабочим набором и переставленными узлами. Сохрани разброс запусков и исключи конкуренцию; не объявляй любой выигрыш NUMA по одному числу.',
    'Почему больше потоков не гарантирует меньшую задержку? Через день нарисуй путь CPU к локальной и удалённой памяти.',
    'https://docs.kernel.org/admin-guide/mm/numa_memory_policy.html')
add('ecc', 'Различить исправленную ошибку памяти и доказанное исправное состояние.',
    'ECC обнаруживает и в рамках конкретного кода исправляет определённые ошибки. Corrected error означает исправление зарегистрированного события, а не отсутствие проблемы. Uncorrected error имеет другую тяжесть и требует процедуры платформы. Счётчики нужно связывать со временем, каналом, DIMM и топологией; подпись слота в журнале сверяют с документацией платы. Отсутствие EDAC в госте не доказывает отсутствие ошибок физической памяти. Подмена DIMM наугад без привязки может затронуть исправный модуль.',
    'EDAC: CE на channel 1, DIMM B2\nза час: +25 CE\nUE: 0\nфизическая карта слотов пока не сверена',
    'Ошибки исправлялись, но рост требует исследования. Из данных нельзя безопасно назначить замену физического модуля только по несверенной подписи.',
    'Предскажи, чем разовый счётчик отличается от прироста. Раздели историю, текущий интервал и идентичность модуля. Составь список наблюдений EDAC/BMC и карты слотов.',
    'В другом наборе CE не растёт после миграции нагрузки. Объясни, почему это не отменяет историческое событие и какие условия нужны для повторного испытания.',
    'Что подтверждает ECC и чего не подтверждает? Позже разбери новую карту каналов без перестановки реального оборудования.',
    'https://docs.kernel.org/driver-api/edac.html')
add('pcie', 'Отделить обнаружение PCIe-функции от работоспособности передачи данных.',
    'PCIe соединяет устройства через порты и коммутаторы. BDF обозначает bus:device.function в данной топологии, а не постоянный серийный номер платы. lspci показывает обнаруженные функции, capability и привязанный драйвер; наличие записи не доказывает успешный DMA или нужную скорость полезной нагрузки. Скорость и ширина согласованного линка могут отличаться от максимума устройства. AER сообщает ошибки пути, которые нужно связывать с портом, временем и нагрузкой.',
    'lspci -Dnnk',
    'Видны BDF, vendor/device ID и Kernel driver in use при привязке. Отсутствующий драйвер отличается от отсутствующей функции.',
    'Предскажи, какие устройства виртуальны. Подготовь pcie, сохрани observation.txt и выбери одну функцию. Раздели обнаружение, драйвер и прикладное испытание устройства.',
    'Разбери данные: capability x8, согласовано x4, ошибок нет. Укажи, что уже известно, а что требует проверки слота и нагрузки; не объявляй устройство сломанным.',
    'Почему успешный lspci не доказывает успешное чтение диска за контроллером? Повтори цепочку с сетевой картой.',
    'https://docs.kernel.org/PCI/pcieaer-howto.html')
add('device-id', 'Связать имя интерфейса с устройством и драйвером через sysfs.',
    'Имя eth0 или enp… — представление сетевого интерфейса, а не достаточное описание физического порта. sysfs показывает связи объектов ядра; ссылка device/driver помогает узнать привязанный драйвер. MAC может быть изменён или виртуализирован, поэтому его используют вместе с топологией и карточкой оборудования. Один адаптер может предоставлять несколько функций или виртуальных интерфейсов. Loopback не обязан иметь физическое device/driver.',
    'ip -br link\nreadlink -f /sys/class/net/eth0/device/driver',
    'Имя eth0 в своей среде нужно заменить фактическим. Для аппаратного или виртуального устройства видна ссылка на драйвер, если она представлена; для lo её может не быть.',
    'Предскажи связь интерфейса с PCI-функцией. Подготовь device-id, перечисли интерфейсы и ссылки на драйверы, сохрани observation.txt. Отметь виртуальные интерфейсы отдельно.',
    'После новой подготовки повтори без запоминания eth0. Найди интерфейс по карте среды и сопоставь с sysfs, не переименовывая его ради совпадения примера.',
    'Почему BDF и имя интерфейса могут измениться после изменения топологии? Через день восстанови соответствие по нескольким признакам.',
    'https://docs.kernel.org/admin-guide/sysfs-rules.html')
add('bmc', 'Собрать независимые сведения о сервере при отказе основной ОС.',
    'BMC — отдельная подсистема управления с собственными питанием, прошивкой, сетью и журналами. Доступность BMC не гарантирует работоспособность основной ОС и наоборот. Показания датчиков зависят от единиц, порогов, времени обновления и состояния платформы. SEL может содержать исторические события и неверное календарное время. Удалённая консоль даёт наблюдение за загрузкой, но сброс питания — отдельное изменяющее действие с риском потери данных.',
    'BMC доступен\nОС не отвечает по сети\nдатчик PSU1: present\nSEL: старое событие потери питания',
    'Нельзя заключить, что ОС загружена или что питание сейчас неисправно. Нужно сверить текущее состояние, время события и консоль.',
    'Предскажи, какие факты можно получить без ОС. По данным раздели датчики, журнал и консоль; составь последовательность чтения до любого power reset.',
    'В новом случае консоль показывает работающую ОС, но SSH недоступен. Выбери сетевую проверку гостевой ОС, не перезагружая сервер только из-за доступности BMC.',
    'Какие учётные данные и каналы управления должны сохраняться при аварии ОС? Аппаратный навык здесь требует настоящего BMC.',
    'https://www.dmtf.org/standards/redfish')
add('power', 'Проверить резерв питания от блока до независимого источника.',
    'Два блока питания не дают резервирование всей цепочки, если оба подключены к одному PDU, UPS или вводу. Нужно учесть суммарную нагрузку после отказа одной ветви, возможности оставшегося блока и охлаждение. Наличие зелёного индикатора не является испытанием под нагрузкой. Отключение реального питания требует согласованной процедуры и контроля данных; в этом уроке без подходящего оборудования разбирается схема, а не засчитывается физический отказ.',
    'PSU1 → PDU-A → UPS-1\nPSU2 → PDU-B → UPS-1\nнагрузка 900 W; каждый PSU рассчитан на 1200 W в данных условиях',
    'Отказ одного PSU может быть покрыт по мощности, но UPS-1 остаётся общей точкой отказа. Паспортная мощность проверяется для фактического входа и режима.',
    'Предскажи последствия каждого одиночного отказа. Нарисуй обе ветви до ввода, отметь общие узлы и нагрузку оставшейся ветви.',
    'Разнеси ветви на два UPS, но оставь общий ввод. Пересмотри список покрытых отказов и способ проверки сигнализации.',
    'Почему резерв мощности отличается от независимости? Вернись к карте питания вместе с картой сети.',
    'https://www.opencompute.org/wiki/Server/SpecsAndDesigns')
add('uefi', 'Подтвердить UEFI-загрузку ВМ и место передачи управления ОС.',
    'UEFI — интерфейс прошивки платформы и загрузочных приложений. BootOrder задаёт порядок записей загрузки, а запись обычно указывает на путь EFI-приложения и устройство. Наличие файла на ESP не доказывает, что запущен именно он. После загрузки Linux каталог /sys/firmware/efi свидетельствует о UEFI-режиме этой загрузки; в legacy-режиме он обычно отсутствует. OVMF позволяет исследовать UEFI внутри ВМ, но не подтверждает прошивку физического сервера.',
    'test -d /sys/firmware/efi && printf "UEFI\\n"\nfind /sys/firmware/efi/efivars -maxdepth 1 -name "BootOrder-*"',
    'В OVMF-госте видны UEFI и переменная BootOrder. Отсутствие каталога означает невыполненную предпосылку этой работы, а не успешную проверку UEFI.',
    'Предскажи режим по карточке ВМ. Подготовь uefi, прочитай признаки режима и сохрани observation.txt. Сопоставь с выбором firmware в Proxmox без изменения реального хоста.',
    'Разбери случай: BootOrder указывает на удалённый EFI-файл. Отдели неверную запись от отсутствующего диска и от отказа уже запущенного ядра.',
    'Что нужно доказать сверх наличия ESP? Через день нарисуй границу UEFI application → loader → kernel.',
    'https://uefi.org/specifications')
add('secure-boot', 'Определить, какой объект и каким ключом проверяет Secure Boot.',
    'Secure Boot проверяет допустимость загрузочных образов по политике платформы. PK, KEK, db и dbx имеют разные роли управления доверием и отзывом. Подпись образа не означает отсутствие ошибок в коде, а разрешение старого подписанного образа зависит также от отзывов и последующих звеньев. TPM measured boot измеряет компоненты и решает другую задачу. Изменение ключей платформы может нарушить загрузку; без отдельной подготовленной ВМ этот урок остаётся анализом.',
    'образ подписан ключом K\nK присутствует в db\nхеш образа присутствует в dbx\nпроверка включена',
    'Наличие доверенного ключа само по себе не разрешает отозванный образ. Для конкретного результата нужно применить политику версии прошивки.',
    'Предскажи роль dbx в примере. Нарисуй проверяемый образ, подпись и базы; отдельно отметь, что измеряет TPM и кто оценивает измерения.',
    'Измени пример: образ подписан неизвестным ключом, отзывов нет. Объясни, почему отсутствие записи в dbx не создаёт доверия.',
    'Чем разрешённый запуск отличается от доказанной безопасности программы? Аппаратное испытание не засчитывается по скриншоту настроек.',
    'https://uefi.org/specs/UEFI/2.10/32_Secure_Boot_and_Driver_Signing.html')
add('firmware-phases', 'Разместить наблюдаемый отказ в цепочке ранней инициализации прошивки.',
    'В архитектуре UEFI PI фазы SEC, PEI, DXE и BDS описывают разные этапы инициализации и выбора загрузки. Ранняя доступность памяти и устройств развивается постепенно; наличие сообщения одной фазы не доказывает завершение последующей. POST-коды и строки serial log имеют смысл в контексте конкретной платформы и версии сборки. Реконструкция по журналу должна отделять последний подтверждённый этап от предположения о причине.',
    'журнал: PEI завершена\nжурнал: DXE dispatcher запущен\nзаписи BDS отсутствуют',
    'Подтверждён вход в DXE, но отсутствие записи BDS не доказывает конкретный отказ одного драйвера: возможны остановка, фильтр или неполный захват.',
    'Предскажи, какие ресурсы уже могли быть доступны. Отметь на цепочке подтверждённые переходы и запроси следующий различающий источник: полный serial log, код платформы, состояние захвата.',
    'Разбери другой журнал с запуском EFI loader. Перенеси границу поиска вперёд и объясни, почему перепрошивка не следует автоматически из любого зависания.',
    'Почему POST-код без модели и версии недостаточен? Повтори разбор виртуального OVMF-журнала.',
    'https://uefi.org/specs/PI/1.8/')
add('acpi', 'Различить описание ресурсов ACPI и их фактическое использование ОС.',
    'ACPI передаёт ОС описание устройств, методов управления и топологии. MADT относится к процессорам и контроллерам прерываний, SRAT — к близости CPU и памяти, SLIT — к относительным расстояниям NUMA. Таблица описывает данные прошивки; ядро может отклонить некорректные сведения или использовать fallback. Обнаруженное PCI-устройство и выделенные ему MMIO-ресурсы также различаются. Нельзя выводить исправность всех таблиц из одной успешной загрузки.',
    'SRAT: два узла\nядро: сообщение об отклонении записи SRAT\nlscpu: один узел',
    'Описание прошивки и применённая ядром топология не совпали. Вывод о реальной NUMA-разбивке требует сообщения ядра и других источников.',
    'Предскажи, какой источник отвечает за описание, а какой — за принятое состояние. По данным раздели таблицы, журнал проверки и sysfs-топологию.',
    'Разбери PCI-функцию, обнаруженную без назначенного BAR. Укажи, почему это не одно и то же, что отсутствие устройства, и какой ресурсный конфликт искать.',
    'Почему загрузка ОС не является полной приёмкой ACPI? Изменение таблиц на физической плате в этот опыт не входит.',
    'https://uefi.org/specifications')
add('firmware-update', 'Подготовить проверяемый план обновления с возможностью восстановления.',
    'Обновление прошивки меняет код платформы и иногда формат переменных и данных. Совпадение семейства процессора не доказывает совместимость образа с моделью и ревизией платы. Нужны происхождение, контрольная сумма, состав регионов, требования версии и способ возврата. Чтение и запись файла на диске не подтверждают запись SPI. Даже совпадение readback не доказывает загрузку и корректность всех функций. Отдельно сохраняют уникальные данные платы, если это предусмотрено процедурой производителя.',
    'плата: модель A, ревизия 2\nобраз: модель A, ревизия 1\nсовместимость ревизий: не подтверждена\nспособ восстановления: не испытан',
    'План пока не готов к записи. Название модели и наличие файла не закрывают совместимость и восстановление.',
    'Предскажи риск каждого пробела. Составь карточку: устройство, текущая версия, целевая версия, источник, SHA-256, сохраняемые данные, питание, процедура восстановления и проверки после запуска.',
    'Для OVMF-ВМ подготовь копию firmware vars и виртуального диска. Раздели файловую подготовку, запуск виртуальной системы и неподтверждённый навык физической прошивки.',
    'Какие доказательства нужны после записи кроме контрольной суммы? Без подходящего устройства аппаратная часть остаётся непроверенной.',
    'https://uefi.org/specs/UEFI/2.10/23_Firmware_Update_and_Reporting.html')
add('redfish', 'Прочитать управление платформой как API с проверяемыми ресурсами и правами.',
    'Redfish описывает ресурсы управления платформой через HTTP и JSON. URI из ответа нужно обходить по ссылкам сервиса, а не угадывать все пути по одному примеру производителя. Systems, Chassis и Managers описывают разные объекты. Аутентификация, права и состояние задачи важны отдельно от кода HTTP. Изменяющая операция может быть асинхронной и требовать проверки Task. Пароли и токены не сохраняют в учебных отчётах; самоподписанный сертификат требует явной процедуры доверия.',
    'GET /redfish/v1/ → ссылки Systems, Chassis, Managers\nGET по ссылке Systems → коллекция Members\nGET выбранного Member → состояние системы',
    'Один успешный GET корня не подтверждает доступ ко всем ресурсам или право менять питание. Идентификатор Member зависит от сервиса.',
    'Предскажи, почему статический путь Systems/1 может отсутствовать. По предоставленному JSON пройди ссылки до нужной системы и сохрани только несекретные поля состояния.',
    'Коллекция содержит несколько Members и nextLink. Выбери систему по проверенному идентификатору и учти пагинацию; не отправляй Reset в опыте чтения.',
    'Как отличить 401, 403 и отсутствие ресурса? Через день пройди другой ответ без запоминания URI производителя.',
    'https://www.dmtf.org/standards/redfish')

add('monitor', 'Выбрать измерение, отражающее получение заметки пользователем.',
    'Метрика описывает определённую величину, точку съёма и интервал. Доступность процесса, доля успешных запросов и задержка ответа — разные сигналы. Counter накапливает события и может сбрасываться; gauge показывает состояние, histogram хранит распределение в корзинах. Для доли ошибок нужны согласованные числитель и знаменатель. Высокая кардинальность labels, например пользовательский текст заметки, делает наблюдение дорогим и может раскрыть данные.',
    'за 5 минут: 1000 запросов, 20 ошибок\nпроцесс запущен\n95% успешных ответов быстрее 200 ms',
    'Доля ошибок равна 2%. Состояние процесса не отменяет эти ошибки. Процентиль успешных ответов не включает доступность автоматически.',
    'Предскажи, какой сигнал первым отражает отказ чтения заметки. Определи endpoint, класс успеха, окно, timeout и отдельный счётчик ошибок.',
    'Сервис отвечает быстро, но неправильным содержимым. Добавь ограниченную проверку смысла ответа и объясни, почему одной latency недостаточно.',
    'Какие labels нужны и какие нельзя помещать в метрики? Через день проверь другой пользовательский путь.',
    'https://prometheus.io/docs/practices/instrumentation/')
add('alert', 'Сформулировать оповещение, требующее конкретного действия.',
    'Оповещение полезно, когда сообщает о значимом нарушении и ведёт к понятному действию. Порог CPU сам по себе не выражает ущерб пользователю. SLI измеряет поведение, SLO задаёт цель на окне, error budget описывает допустимый объём неуспеха. Условие, длительность, маршрутизация и инструкция реагирования должны быть согласованы. Приёмка проверяет доставку и восстановление сигнала, а не только синтаксис правила.',
    'условие: доля ошибок чтения > 5% в течение 10 минут\nдействие: проверить внешний запрос, затем путь к программе\nвосстановление: доля ошибок вернулась в допустимый диапазон',
    'В правиле есть воздействие, окно и действие. Для применения ещё нужны достаточный трафик, адресат и проверенная доставка.',
    'Предскажи поведение при одном запросе в час. Добавь правило обработки малого трафика и инструкцию первых наблюдений без автоматической перезагрузки.',
    'В новом наборе CPU=95%, но SLI в норме. Объясни разницу между предупреждением ёмкости и срочным вызовом по пользовательскому отказу.',
    'Как проверить, что сигнал действительно снялся после восстановления? Через день проиграй тестовый сигнал по инструкции.',
    'https://sre.google/workbook/alerting-on-slos/')
add('access', 'Проверить разрешение конкретному субъекту на конкретное действие.',
    'Аутентификация устанавливает личность, авторизация определяет разрешённые действия. Успешный вход не даёт право читать любую заметку. Минимальные привилегии относятся к задаче и среде, а не к удобству администратора. Ключ, токен и пароль требуют отдельного жизненного цикла и отзыва. Проверка включает разрешённое действие и запрещённый соседний случай; ответ интерфейса не заменяет проверку серверной стороны.',
    'пользователь A владеет заметкой A\nпользователь B владеет заметкой B\nA пытается прочитать B',
    'Корректная модель должна отклонить чужое чтение даже при действительной сессии A. Скрытая кнопка в браузере этого не обеспечивает.',
    'Предскажи различие 401 и 403 по контракту приложения. Составь матрицу субъект → объект → действие и по одному положительному и отрицательному тесту.',
    'Учётная запись службы получила административную роль ради чтения одного файла. Предложи более узкое разрешение и проверку после отзыва лишних прав.',
    'Что нужно проверить до отключения парольного входа в SSH? Ответ: новый ключевой вход в отдельном соединении и доступный канал восстановления.',
    'https://www.rfc-editor.org/rfc/rfc9110.html')
add('tls', 'Проверить доверие сертификату и имя узла как независимые условия.',
    'TLS защищает транспорт при корректной проверке другой стороны. Сертификат связывает ключ с именами в рамках цепочки доверия и срока действия. Совпадение имени не делает неизвестный ключ доверенным; доверенная цепочка не разрешает сертификат для другого имени. В примере используется отдельный учебный сертификат и явный CAfile, без установки доверия всей системе. Отключение проверки через -k скрывает проблему и не подтверждает правильный TLS.',
    'openssl verify -CAfile "$WORK/cert.pem" -verify_hostname notes.test "$WORK/cert.pem"\nopenssl verify -CAfile "$WORK/cert.pem" -verify_hostname other.test "$WORK/cert.pem"',
    'Первая проверка проходит, вторая возвращает hostname mismatch. Оба результата получены на одном сертификате.',
    'Предскажи два исхода. Подготовь tls, сохрани valid.txt и wrong.txt, не подавляя вторую ошибку как успех. Прочитай SAN сертификата.',
    'Повтори с новой попыткой и объясни результат проверки без CAfile. Не меняй системные сертификаты и не публикуй закрытый ключ.',
    'Почему успешная проверка сертификата ещё не подтверждает правильное содержимое заметки? Через день разложи цепочку доверие → имя → протокол → приложение.',
    'https://docs.openssl.org/3.0/man1/openssl-verification-options/')
add('time', 'Оценить сопоставимость событий разных узлов с учётом погрешности часов.',
    'Календарные часы нужны для меток времени, но могут корректироваться. Синхронизация не означает нулевую погрешность; важны источник, смещение, дисперсия и время последнего обновления. Timezone меняет отображение, а не физический момент события. NTPSynchronized сообщает состояние механизма, но сам по себе не задаёт верхнюю границу ошибки. Если интервалы неопределённости двух событий перекрываются, их строгий порядок по меткам не доказан.',
    'timedatectl show -p NTPSynchronized -p Timezone',
    'Вывод содержит состояние и часовой пояс. Без измеренной границы ошибки нельзя обещать точный межузловой порядок.',
    'Предскажи, даст ли смена timezone синхронизацию. Подготовь time и сохрани clock.txt. Отдельно запроси фактическое смещение у используемой службы синхронизации.',
    'A: 12:00:00.100 ±80 ms; B: 12:00:00.150 ±80 ms. Покажи перекрытие интервалов и объясни, почему порядок не доказан.',
    'Какие данные потребуются для более точного вывода? Через день разбери неперекрывающиеся интервалы.',
    'https://www.freedesktop.org/software/systemd/man/latest/timedatectl.html')
add('duration', 'Измерить длительность без зависимости от коррекции календарных часов.',
    'Длительность локальной операции измеряют разностью подходящих монотонных часов. Календарная разность может исказиться при коррекции времени. Монотонная шкала не задаёт универсальный момент между компьютерами и загрузками. В Linux CLOCK_MONOTONIC и CLOCK_BOOTTIME отличаются учётом сна системы; выбор зависит от требуемого контракта. Нужно записывать единицы и границы операции, а не только результат.',
    'start_monotonic=100.0 s\nend_monotonic=100.4 s\nкалендарные часы во время операции скорректированы назад на 1 s',
    'Локальная длительность по монотонной шкале — 0.4 s. Отрицательная календарная разность не означает отрицательное время выполнения.',
    'Предскажи эффект коррекции на два измерения. Запиши начало и конец операции и назови подходящую шкалу для ответа клиенту.',
    'Вариант: ноутбук уснул на десять минут. Уточни, нужно ли включать сон в длительность; только после этого выбери тип часов.',
    'Почему нельзя вычитать monotonic разных машин? Через день измерь локальный опыт с явными единицами.',
    'https://man7.org/linux/man-pages/man2/clock_gettime.2.html')
add('availability', 'Найти общий отказ в схеме с резервными компонентами.',
    'Доступность относится к функции и интервалу, а не просто к числу копий. Два сервера могут зависеть от одного коммутатора, массива, DNS или оператора. Последовательные и параллельные формулы вероятностей требуют предположений о независимости и режиме отказов; коррелированные события нарушают простое умножение. Failover включает обнаружение, решение, переключение и проверку. Данные могут сохраниться, а время переключения всё равно нарушить допустимость для приложения.',
    'два сервера → один коммутатор → один массив\nтайм-аут клиента 20 s\nпереключение 35 s',
    'Общий коммутатор и массив остаются точками отказа. Переключение дольше ожидания клиента на 15 s, даже если данные целы.',
    'Предскажи результат отказа каждого общего узла. Нарисуй домены отказа и отдельно оцени непрерывность данных и допустимую паузу.',
    'Добавь независимый сетевой путь, сохрани общий массив. Назови покрытый отказ и остаточный риск вместо заявления «система полностью отказоустойчива».',
    'Как испытание одного отказа ограничивает вывод? Через день проверь карту питания той же системы.',
    'https://sre.google/sre-book/availability-table/')
add('recovery-time', 'Разложить время восстановления на измеримые этапы.',
    'Время возврата функции включает обнаружение, подтверждение, выбор действия, выполнение и проверку. Быстрое копирование не уменьшает долгую задержку обнаружения автоматически. RTO — цель, фактическая длительность — результат конкретного прогона. Среднее время не описывает худшие случаи. Процедура сокращает время только если доступна при отказе и проверена на подходящих ресурсах.',
    'обнаружение 8 min\nразбор 12 min\nвосстановление 5 min\nпроверка 3 min\nцель 20 min',
    'Всего 28 min; цель не выполнена. Ускорение копирования на одну минуту оставит значительный дефицит.',
    'Предскажи самый полезный участок улучшения. Посчитай сумму, предложи более раннее обнаружение или заранее проверенное решение и укажи способ измерить эффект.',
    'В новом прогоне обнаружение 2 min, но процедура требует недоступного пароля. Объясни, почему старые пять минут восстановления больше не применимы.',
    'Когда начинается и заканчивается твой таймер? Через день составь протокол без скрытых ожиданий.',
    'https://sre.google/sre-book/managing-incidents/')
add('incident', 'Восстановить конкретную службу, сохранив наблюдение до изменения.',
    'Инцидент начинается с нарушенной функции, а не с выбранной причины. Сначала проверяют масштаб, среду и последние изменения, затем собирают минимальные различающие факты. Сохранённое исходное состояние помогает объяснить результат и не повторять случайные действия. Восстановление может быть откатом или исправлением; после него нужен тот же пользовательский запрос и контроль соседних функций. Коммуникация фиксирует факты и неопределённости отдельно.',
    'sudo systemctl show "$NS.service" -p ActiveState -p SubState\ncurl --fail --max-time 3 http://127.0.0.1:18080/',
    'В подготовленном incident служба остановлена. before.txt должен фиксировать inactive до запуска, затем проверка требует active и тело note.',
    'Предскажи состояние и запрос. Сохрани systemctl show в before.txt до исправления. Запусти только свой unit и повтори HTTP; сравни с исходным наблюдением.',
    'Повтори второй вариант, найдя порт из unit. Напиши короткий разбор: эффект, факт до, изменение, факт после и что ещё не доказано.',
    'Почему отсутствие симптома в один момент не устанавливает первопричину? Через день разбери другой отказ без перезапуска всего стенда.',
    'https://sre.google/sre-book/effective-troubleshooting/')
add('incident-close', 'Закрыть инцидент по проверенной функции и остаточным рискам.',
    'Закрытие требует критериев восстановления, а не только окончания действий инженера. Проверяют пользовательский путь, данные, нагрузку, снятие оповещений и состояние резервирования. Временное обходное решение может вернуть функцию, сохранив технический долг и риск. Их фиксируют с владельцем и следующим действием. Разбор отделяет механизм отказа, способ обнаружения и условия повторения; поиск виноватого не заменяет исправления системы.',
    'страница снова отвечает\nRAID остаётся degraded\nоповещение подавлено вручную\nкопия после ремонта не проверена',
    'Функция частично восстановлена, но нельзя объявить полное штатное состояние. Избыточность, сигнализация и копия требуют отдельных действий.',
    'Предскажи, какие пункты мешают окончательному закрытию. Составь критерии и для каждого укажи проверяемый факт, владельца и остаточное ограничение.',
    'В новом наборе все технические показатели нормальны, но пользователь получает старую заметку. Добавь проверку данных и пересмотри закрытие.',
    'Чем восстановление функции отличается от устранения причины? Вернись к разбору через день и выбери профилактическое изменение.',
    'https://sre.google/sre-book/postmortem-culture/')
add('migration', 'Перенести данные с единственным источником записи и проверяемым возвратом.',
    'Миграция меняет место или формат состояния. Пока данные продолжают меняться, разовое копирование быстро устаревает. Нужно определить источник истины, синхронизацию дельты, момент остановки старой записи и проверку новой. Два независимых писателя без протокола согласования создают split brain. План возврата должен учитывать новые записи после переключения; простое переключение DNS назад может их потерять. TTL не гарантирует мгновенного обновления всех клиентов.',
    '10:00 копия old → new\n10:05 новая заметка записана только old\n10:10 клиенты переключены на new',
    'Без переноса дельты заметка 10:05 отсутствует в новой системе. Само успешное копирование 10:00 не доказывает корректную миграцию.',
    'Предскажи расхождение. Составь последовательность: исходная копия, дельта, ограничение записи, финальная сверка, переключение, прикладной запрос.',
    'После переключения на new появились новые записи, затем понадобился возврат. Опиши их перенос обратно или ограничение возврата; не обещай безопасное DNS-переключение без синхронизации.',
    'В какой момент разрешено вывести старую систему? Через день проверь миграционный план на незнакомом наборе записей.',
    'https://sre.google/workbook/data-processing/')
add('decommission', 'Вывести старую систему, закрыв зависимости, доступ и данные.',
    'Остановка машины не завершает вывод из эксплуатации. Остаются DNS, мониторинг, задания резервного копирования, ключи, учётные записи, лицензии и данные на носителях. Перед удалением подтверждают отсутствие активных потребителей, пригодность нужных архивов и требования хранения. Очистка файла и санитизация физического носителя имеют разные гарантии, особенно для SSD и резервных копий. Необратимые действия выполняют только после проверенного решения о сохранении данных.',
    'новая система обслуживает запросы\nстарый cron ещё отправляет отчёты\nстарый ключ имеет доступ к новой БД',
    'Старая система ещё имеет зависимости и права. Её выключение может скрыть проблему, но не отзывает ключ.',
    'Предскажи два последствия удаления ВМ прямо сейчас. Составь инвентарь потребителей, расписаний, доступов, архивов и носителей, затем критерии безопасного завершения.',
    'К старому адресу обращается редкий месячный отчёт. Предложи окно наблюдения и способ выявить зависимость до удаления, учитывая периодичность.',
    'Чем удалённая ВМ отличается от отозванных секретов? Позже проверь фиктивную карточку вывода по всем границам.',
    'https://csrc.nist.gov/pubs/sp/800/88/r2/final')
add('baseline', 'Сохранить исходные факты среды, позволяющие сравнить результат изменения.',
    'Базовая линия фиксирует версию системы, конфигурацию, данные, нагрузку и условия наблюдения. Без неё улучшение нельзя уверенно приписать изменению. Контрольная сумма помогает обнаружить отличие файла, но не объясняет его смысл и не подтверждает запуск программы. Снимок и отчёт дополняют друг друга: один возвращает состояние в пределах своего охвата, другой описывает проверенные факты. Персональные данные и секреты из карточки исключают.',
    'hostname\ncat /etc/os-release\nlsblk -J -o NAME,TYPE,SIZE\nip -j address show lo\nsha256sum /etc/os-release',
    'Сформирована воспроизводимая карточка гостя без текста личных заметок и паролей. Она относится к конкретной попытке и времени.',
    'Предскажи, какие поля изменятся после новой установки ОС. Подготовь baseline, собери observation.txt и сопоставь с карточкой ВМ.',
    'После новой подготовки повтори сбор. Объясни, какие изменения допустимы и какие делают сравнение двух опытов некорректным.',
    'Почему сохранённый JSON не доказывает текущее состояние через неделю? Через день восстанови среду по карточке и отметь несовпадения.',
    'https://sre.google/sre-book/release-engineering/')
add('unknown-incident', 'Самостоятельно восстановить HTTP-путь, сохранив проверяемую цепочку фактов.',
    'Итоговая задача объединяет знакомые границы: клиент, маршрут, порт, процесс, конфигурация и данные. Название симптома не является причиной. Выбирай следующую проверку по тому, какие гипотезы она различает, и меняй минимально необходимое. Сохрани исходный факт до исправления, повтори пользовательский запрос после и проверь сохранность заметки. Исполнитель подтверждает только наблюдаемые условия; качество собственного объяснения обсуждается отдельно.',
    'симптом: локальный запрос к заметке не проходит\nисходные факты: собери самостоятельно\nцель: вернуть ожидаемый ответ, сохранив данные',
    'Готовое решение не показано. Отчёт принимается только для текущей попытки после проверки фактов; чужой или старый успех не засчитывается.',
    'Перед подготовкой запиши порядок границ, которые умеешь проверять. Подготовь unknown-incident; сначала собери наблюдения процесса и unit, сохрани исходный ExecStart в before.txt, затем выбери одну гипотезу.',
    'Восстанови ответ самостоятельно и напиши: почему выбранное изменение объясняет факты и какие альтернативы остались. Откати, подготовь другой вариант и повтори без прошлого отчёта.',
    'Через день реши новый случай с другой причиной на том же пользовательском пути. Скорость выполнения не заменяет доказательства и сохранность данных.',
    'https://sre.google/sre-book/effective-troubleshooting/')
